CREATE DATABASE IF NOT EXISTS smart_id CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE smart_id;
CREATE TABLE settings(id INT AUTO_INCREMENT PRIMARY KEY, setting_key VARCHAR(100) UNIQUE NOT NULL, setting_value TEXT, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE roles(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) UNIQUE NOT NULL, permissions TEXT) ENGINE=InnoDB;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role VARCHAR(50) NOT NULL DEFAULT 'admin', permissions TEXT, status ENUM('active','inactive') DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE departments(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, status ENUM('active','inactive') DEFAULT 'active') ENGINE=InnoDB;
CREATE TABLE classes(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, status ENUM('active','inactive') DEFAULT 'active') ENGINE=InnoDB;
CREATE TABLE categories(id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, status ENUM('active','inactive') DEFAULT 'active') ENGINE=InnoDB;
CREATE TABLE members(id BIGINT AUTO_INCREMENT PRIMARY KEY, member_uid VARCHAR(60) UNIQUE NOT NULL, verify_token VARCHAR(64) UNIQUE NOT NULL, full_name VARCHAR(160) NOT NULL, father_name VARCHAR(160), mother_name VARCHAR(160), gender VARCHAR(30), dob DATE NULL, blood_group VARCHAR(10), nationality VARCHAR(80), religion VARCHAR(80), address TEXT, district VARCHAR(100), state VARCHAR(100), country VARCHAR(100), phone VARCHAR(40), whatsapp VARCHAR(40), email VARCHAR(190), emergency_contact VARCHAR(80), occupation VARCHAR(120), qualification VARCHAR(120), joining_date DATE NULL, status ENUM('active','inactive','expired','blocked') DEFAULT 'active', department_id INT NULL, class_id INT NULL, category_id INT NULL, roll_number VARCHAR(60), admission_number VARCHAR(80), rfid_number VARCHAR(80), gps_address VARCHAR(255), notes TEXT, photo VARCHAR(255), signature VARCHAR(255), barcode VARCHAR(120), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_member_search(full_name,member_uid,email), FOREIGN KEY(department_id) REFERENCES departments(id) ON DELETE SET NULL, FOREIGN KEY(class_id) REFERENCES classes(id) ON DELETE SET NULL, FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE member_files(id BIGINT AUTO_INCREMENT PRIMARY KEY, member_id BIGINT NOT NULL, category ENUM('profile','signature','documents','certificates','payments','attendance','gallery','other') NOT NULL DEFAULT 'documents', file_name VARCHAR(190) NOT NULL, original_file_name VARCHAR(190) NOT NULL, file_path VARCHAR(255) NOT NULL, mime_type VARCHAR(120), file_extension VARCHAR(20), file_size BIGINT DEFAULT 0, uploaded_by INT NULL, status ENUM('active','archived','deleted') DEFAULT 'active', notes TEXT, uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_member_files(member_id,category,status), FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE, FOREIGN KEY(uploaded_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE member_documents(id BIGINT AUTO_INCREMENT PRIMARY KEY, member_id BIGINT NOT NULL, title VARCHAR(150), file_path VARCHAR(255) NOT NULL, visibility ENUM('public','private') DEFAULT 'private', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE id_cards(id BIGINT AUTO_INCREMENT PRIMARY KEY, member_id BIGINT NOT NULL, template VARCHAR(80) DEFAULT 'premium', orientation ENUM('portrait','landscape','wallet','a4') DEFAULT 'portrait', issue_date DATE, expiry_date DATE, status ENUM('active','expired','revoked') DEFAULT 'active', FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE payments(id BIGINT AUTO_INCREMENT PRIMARY KEY, member_id BIGINT, amount DECIMAL(10,2), method VARCHAR(40), status VARCHAR(40), paid_at DATETIME, FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE attendance(id BIGINT AUTO_INCREMENT PRIMARY KEY, member_id BIGINT, check_in DATETIME, check_out DATETIME, source VARCHAR(40), FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE form_fields(id INT AUTO_INCREMENT PRIMARY KEY, form_name VARCHAR(80), field_name VARCHAR(80), label VARCHAR(120), placeholder VARCHAR(190), field_order INT DEFAULT 0, enabled TINYINT(1) DEFAULT 1, required TINYINT(1) DEFAULT 0, public_visible TINYINT(1) DEFAULT 0, editable TINYINT(1) DEFAULT 1, validation VARCHAR(190), dropdown_values TEXT, UNIQUE KEY uniq_field(form_name,field_name)) ENGINE=InnoDB;
CREATE TABLE activity_logs(id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id INT NULL, action VARCHAR(80), entity VARCHAR(80), entity_id BIGINT NULL, ip_address VARCHAR(64), user_agent VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_logs(created_at,entity)) ENGINE=InnoDB;
